//! The algebra word problems, one per wording.  The Ready ones are operators ("word:age/0002") whose boxes are the numbers of the problem's equation; computing
//! puts the boxes' numbers into the problem text and asks the Rust solver (the port of `operators_one_algebra_word_problem_per_file/_solve.py`).
//! The data is generated by `operator_keys/make_rust_words.py` (words_data.rs).

use super::words_data::{ITEMS, OPERATORS, SPECS};
use crate::operator::Operator;
use crate::value::Value;
use crate::word_solver::{self, q::Q};

/// One problem of the catalog (`operators_one_algebra_word_problem_per_file/INDEX.md`).
pub struct Item {
    pub key: &'static str,
    pub category: &'static str,
    pub id: &'static str,
    pub problem: &'static str,
    /// A solver answers it today (Ready); otherwise it is reference only.
    pub ready: bool,
}

/// What a Ready problem needs to be computed.
pub struct Spec {
    /// The text with every number replaced by `{0}`, `{1}` ...
    pub template: &'static str,
    /// The numbers as written in the text.
    pub numbers: &'static [&'static str],
    /// `word_solver` or `number_puzzle`.
    pub solver: &'static str,
    /// The place (in `numbers`) of each box's number.
    pub box_index: &'static [usize],
    /// The boxes' numbers as written in the stored problem.
    pub defaults: &'static [&'static str],
}

/// All 1,000 problems, in catalog order.
pub fn items() -> &'static [Item] {
    ITEMS
}

/// The Ready problems as operators (key `word:<folder key>`).
pub fn operators() -> &'static [Operator] {
    OPERATORS
}

pub fn get(key: &str) -> Option<&'static Operator> {
    OPERATORS.iter().find(|o| o.key == key)
}

/// The boxes' starting numbers of a Ready problem (a word problem starts with its own numbers; change them and press `=`).
pub fn defaults(key: &str) -> Option<&'static [&'static str]> {
    let i = OPERATORS.iter().position(|o| o.key == key)?;
    Some(SPECS[i].defaults)
}

/// A number as it is written in a problem: 12 -> "12", 2.5 -> "2.5".
fn number_text(x: f64) -> String {
    if x.fract() == 0.0 && x.abs() < 1e15 {
        format!("{}", x as i64)
    } else {
        format!("{x}")
    }
}

/// Python's `template.format(*texts)`: `{0}` is filled, `{{` and `}}` are literal braces.
fn fill(template: &str, texts: &[String]) -> Result<String, String> {
    let mut out = String::new();
    let mut chars = template.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '{' if chars.peek() == Some(&'{') => {
                chars.next();
                out.push('{');
            }
            '}' if chars.peek() == Some(&'}') => {
                chars.next();
                out.push('}');
            }
            '{' => {
                let mut n = String::new();
                for d in chars.by_ref() {
                    if d == '}' {
                        break;
                    }
                    n.push(d);
                }
                let i: usize = n.parse().map_err(|_| "bad template".to_string())?;
                out.push_str(texts.get(i).ok_or_else(|| "This problem needs more numbers.".to_string())?);
            }
            _ => out.push(c),
        }
    }
    Ok(out)
}

fn count_slots(template: &str) -> usize {
    template.matches('{').count() - 2 * template.matches("{{").count()
}

/// An answer as a calculator number.
fn num(q: Q) -> Value {
    Value::Number(q.to_f64())
}

/// Compute the `index`-th Ready problem with the numbers in the boxes.
pub fn run(index: usize, args: &[Value]) -> Result<Value, String> {
    let spec = &SPECS[index];
    let name = OPERATORS[index].name;
    let mut full: Vec<String> = spec.numbers.iter().map(|s| s.to_string()).collect();
    for (place, v) in spec.box_index.iter().zip(args) {
        full[*place] = number_text(v.as_number()?);
    }
    if full.len() != count_slots(spec.template) {
        return Err(format!("This problem needs {} numbers, got {}.", count_slots(spec.template), full.len()));
    }
    let text = fill(spec.template, &full)?;
    let values: Option<Vec<Q>> = if spec.solver == "word_solver" {
        word_solver::solve(&text).map(|r| r.values)
    } else {
        word_solver::solve_number_puzzle(&text).map(|p| vec![p.answer])
    };
    match values {
        Some(v) if !v.is_empty() => Ok(if v.len() == 1 { num(v[0]) } else { Value::List(v.into_iter().map(num).collect()) }),
        _ => Err(format!("{name} can't calculate that: The solver cannot answer this problem with these numbers: {text}")),
    }
}
